import React, { useContext } from 'react';
import { useNavigate } from 'react-router-dom';
import { AuthContext } from '../contexts/AuthContext';
import { useAuth } from '../contexts/AuthContext';


export default function Header() {
  const navigate = useNavigate();
  const { isAuthenticated, logout } = useAuth();

  return (
    <header className="header">
      {/* Верхний блок: логотип | телефон | Авторизация */}
      <div className="header-top">
        <div className="header-item logo-wrap">
          <img src="/static/images/logotypeRGB1.jpg" alt="Логотип" className="logo" />
        </div>
        <div className="header-item phone">
          Телефон: +7 (8325) 20-12-09
        </div>
        <div className="header-item auth-btn">
            {isAuthenticated ? ( 
                <button 
                    className="btn" 
                    onClick={async () => { 
                    await logout(); 
                    navigate("/dashboard", { replace: true }); 
                    }} 
                > 
                    Выход 
                </button> 
            ) : ( 
                <button 
                className="btn" 
                onClick={() => navigate("/login")}
                >
                    Авторизация
                </button> 
            )}
        </div>
      </div>

      {/* Нижний текст, занимает всю ширину экрана */}
      <div className="header-bottom">
        <p>Проверьте комплектацию и тенические характеристики техники Силант</p>
      </div>
    </header>
  );
}
